from collections import defaultdict

# dup_keyが空のものを除外してグループ化
groups = defaultdict(list)
for item in data:
    if item["dup_key"]:
        groups[item["dup_key"]].append(item)

# 重複（2件以上）のみ抽出
duplicates = {k: v for k, v in groups.items() if len(v) > 1}

print(f"重複dup_keyの数: {len(duplicates)}")
print()

# 古い順にソートして古いIDを削除対象に
delete_ids = []
for dup_key, items in sorted(duplicates.items()):
    # created_atで昇順ソート（古い順）
    sorted_items = sorted(items, key=lambda x: x["created_at"])
    # 最新1件を残して、それ以外を削除対象に
    to_delete = sorted_items[:-1]
    to_keep = sorted_items[-1]
    delete_ids_for_key = [i["id"] for i in to_delete]
    delete_ids.extend(delete_ids_for_key)
    print(f"[{dup_key}]")
    print(f"  残す: id={to_keep['id']} ({to_keep['created_at'][:10]})")
    for d in to_delete:
        print(f"  削除: id={d['id']} ({d['created_at'][:10]})")
    print()

print("=" * 50)
print(f"削除すべきIDの総数: {len(delete_ids)}")
print("削除すべきIDリスト:")
print(sorted(delete_ids))
